import java.util.Scanner;

public class cf723b {
    static final Scanner sc = new Scanner(System.in);

    static int[] documentAnalyser(String doc) {
        boolean inParen = false;
        boolean wasLetter = false;
        int longest = 0;
        int length = 0;
        int words = 0;
        for (char ch : doc.toCharArray()) {
            if (ch == '(') {
                inParen = true;
                wasLetter = false;
                length = 0;
            } else if (ch == ')') {
                inParen = false;
                wasLetter = false;
                length = 0;
            } else if (Character.isLetter(ch)) {
                if (inParen && !wasLetter) {
                    words++;
                } else if (!inParen) {
                    length++;
                    if (length > longest) longest = length;
                }
                wasLetter = true;
            } else {
                wasLetter = false;
                length = 0;
            }
        }
        return new int[]{longest, words};
    }

    public static void main(String[] args) {
        int len = sc.nextInt();
        String text = sc.next();
        int[] ans = documentAnalyser(text);
        System.out.print(ans[0] + " " + ans[1]);
    }
}
